const W = Math.max(1, context.panel.chart.getWidth());
const H = Math.max(1, context.panel.chart.getHeight());
const echarts = context.echarts;

const C = {
  bg0: '#050B16', bg1: '#08111F', card: '#0D1B2E', card2: '#12243A',
  border: 'rgba(174,186,213,0.16)', text: '#F4F7FC', sub: '#AEBAD5', mute: '#7F8DA8',
  cyan: '#17C7D5', purple: '#7C3AED', green: '#14B8A6', orange: '#F59E0B',
  red: '#EF4444', blue: '#38BDF8', gray: '#64748B', yellow: '#EAB308', deepRed: '#DC2626'
};

function vals(f) {
  if (!f || f.values == null) return [];
  if (Array.isArray(f.values)) return f.values;
  if (typeof f.values.toArray === 'function') return f.values.toArray();
  if (f.values.buffer && Array.isArray(f.values.buffer)) return f.values.buffer;
  try { return Array.from(f.values); } catch (e) { return []; }
}

function normalizeTime(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date) return v.getTime();
  if (typeof v === 'object') {
    if (v._d instanceof Date) return v._d.getTime();
    if (typeof v.valueOf === 'function') {
      const vv = v.valueOf();
      if (vv !== v && Number.isFinite(Number(vv))) {
        const n = Number(vv);
        return Math.abs(n) < 1e12 ? n * 1000 : n;
      }
    }
  }
  const n = Number(v);
  if (Number.isFinite(n)) return Math.abs(n) < 1e12 ? n * 1000 : n;
  const parsed = Date.parse(String(v));
  return Number.isFinite(parsed) ? parsed : null;
}

function fmtDateTime(v) {
  const ts = normalizeTime(v);
  if (ts === null) return '—';
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return String(v ?? '—');
  const z = n => String(n).padStart(2, '0');
  return `${z(d.getDate())}/${z(d.getMonth() + 1)}/${d.getFullYear()} ${z(d.getHours())}:${z(d.getMinutes())}`;
}

function ageText(v) {
  const ts = normalizeTime(v);
  if (ts === null) return '—';
  let sec = Math.max(0, Math.floor((Date.now() - ts) / 1000));
  if (sec < 60) return `${sec}s`;
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min} min`;
  const h = Math.floor(min / 60);
  if (h < 24) return `${h}h ${min % 60}m`;
  const days = Math.floor(h / 24);
  return `${days}d ${h % 24}h`;
}

function txt(x, y, text, size, color, weight, align = 'left', extra = {}) {
  return {
    type: 'text', silent: true,
    style: {
      x, y, text: String(text), font: `${weight || 500} ${size}px Inter, sans-serif`,
      fill: color || C.text, textAlign: align, textVerticalAlign: 'middle', ...extra
    }
  };
}

function roundedCard(fill = C.card) {
  return {
    type: 'rect', silent: true,
    shape: { x: 1, y: 1, width: Math.max(0, W - 2), height: Math.max(0, H - 2), r: 14 },
    style: { fill, stroke: C.border, lineWidth: 1, shadowBlur: 18, shadowColor: 'rgba(0,0,0,.18)' }
  };
}

function accentLine(color) {
  return {
    type: 'rect', silent: true,
    shape: { x: 0, y: 0, width: 4, height: H, r: [14, 0, 0, 14] },
    style: { fill: color }
  };
}

function esc(v) {
  return String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function objName(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return v.map(objName).filter(Boolean).join(', ');
  if (typeof v === 'object') {
    return String(v.name ?? v.host ?? v.value ?? v.tag ?? v.description ?? '');
  }
  return String(v);
}

function problemsFromFrames() {
  const frames = (context.panel.data && context.panel.data.series) || [];
  const out = [];
  for (const frame of frames) {
    if (!frame || !frame.fields) continue;
    const pf = frame.fields.find(f => String(f.name).toLowerCase() === 'problems') ||
      frame.fields.find(f => f.config && f.config.custom && f.config.custom.type === 'problems');
    if (!pf) continue;
    for (const p of vals(pf)) {
      if (p && typeof p === 'object') out.push(p);
    }
  }
  return out;
}

const SEV = [
  { short: 'N/C', label: 'Não classificado', color: C.gray },
  { short: 'INFO', label: 'Informação', color: C.blue },
  { short: 'AVISO', label: 'Warning', color: C.yellow },
  { short: 'MÉDIA', label: 'Average', color: C.orange },
  { short: 'ALTA', label: 'High', color: C.red },
  { short: 'DESASTRE', label: 'Disaster', color: C.deepRed }
];

function sevRank(p) {
  const n = Number(p && p.severity);
  return Number.isFinite(n) && n >= 0 && n <= 5 ? n : null;
}

function sevMeta(p) {
  const n = sevRank(p);
  return n === null ? { short: 'N/C', label: 'Não classificado', color: C.gray } : SEV[n];
}

function hostName(p) {
  const hs = p && p.hosts;
  if (Array.isArray(hs) && hs.length) return objName(hs[0]) || '—';
  return objName(hs) || '—';
}

function groupName(p) {
  const gs = p && p.groups;
  if (Array.isArray(gs) && gs.length) return gs.map(objName).filter(Boolean).slice(0, 2).join(' · ') || '';
  return objName(gs);
}

function acknowledged(p) {
  if (!p) return false;
  if (p.acknowledged === true || p.acknowledged === 1 || String(p.acknowledged) === '1') return true;
  return Array.isArray(p.acknowledges) && p.acknowledges.length > 0;
}

function ackSummary(p) {
  const a = Array.isArray(p && p.acknowledges) ? p.acknowledges : [];
  if (!a.length) return 'Sem reconhecimento';
  const last = a[a.length - 1] || {};
  const who = last.user || [last.name, last.surname].filter(Boolean).join(' ') || 'usuário';
  const when = last.time || fmtDateTime(last.clock);
  return `${who}${when && when !== '—' ? ' · ' + when : ''}`;
}

function isRecovered(p) {
  return HISTORY_MODE && String(p && p.value) === '0';
}

function isRecent(p) {
  const ts = normalizeTime(p && p.timestamp);
  if (ts === null) return false;
  return (Date.now() - ts) <= RECENT_MINUTES * 60 * 1000;
}

const HISTORY_MODE = false;
const RECENT_MINUTES = 15;
const MIN_VISIBLE_SEVERITY = 3;

let rows = problemsFromFrames();
rows = rows.filter(p => {
  const s = sevRank(p);
  return s === null || s >= MIN_VISIBLE_SEVERITY;
});
rows.sort((a, b) => {
  const sa = sevRank(a) ?? -1;
  const sb = sevRank(b) ?? -1;
  if (sb !== sa) return sb - sa;
  const ta = normalizeTime(a.timestamp) ?? 0;
  const tb = normalizeTime(b.timestamp) ?? 0;
  return tb - ta;
});

const total = rows.length;
const counts = [0, 0, 0, 0, 0, 0];
let acked = 0;
let recent = 0;
for (const p of rows) {
  const s = sevRank(p);
  if (s !== null) counts[s]++;
  if (acknowledged(p)) acked++;
  if (isRecent(p)) recent++;
}

if (!total) {
  return {
    backgroundColor: 'transparent',
    graphic: [
      roundedCard(), accentLine(C.cyan),
      txt(22, 27, "INCIDENTES ATIVOS · ALTA PRIORIDADE", 14, C.text, 850),
      txt(22, 53, "Problemas ativos Average, High e Disaster · reconhecimento, idade e dados operacionais.", 10, C.sub, 500),
      txt(22, Math.max(105, H * 0.48), 'Nenhum incidente encontrado', 18, C.text, 800),
      txt(22, Math.max(134, H * 0.48 + 30), 'A consulta Zabbix não retornou eventos visíveis para esta classificação.', 11, C.mute, 500)
    ],
    xAxis: { show: false }, yAxis: { show: false }, series: []
  };
}

const visibleRows = Math.max(6, Math.min(13, Math.floor((H - 132) / 38)));
const compactMode = W < 1050;
const showGroup = W >= 1280;
const showOpdata = W >= 1180;
const showAck = W >= 900;

const graphics = [
  roundedCard(), accentLine(C.cyan),
  txt(22, 24, "INCIDENTES ATIVOS · ALTA PRIORIDADE", 14, C.text, 850),
  txt(22, 49, "Problemas ativos Average, High e Disaster · reconhecimento, idade e dados operacionais.", 10, C.sub, 500),
  txt(W - 22, 24, `${total.toLocaleString('pt-BR')} EVENTOS`, 10, C.cyan, 850, 'right'),
  txt(W - 22, 49, `${acked.toLocaleString('pt-BR')} reconhecidos · ${recent.toLocaleString('pt-BR')} recentes`, 9, C.mute, 650, 'right'),

  { type: 'circle', silent: true, shape: { cx: 24, cy: 76, r: 4 }, style: { fill: C.deepRed } },
  txt(34, 76, `Desastre ${counts[5]}`, 9, C.sub, 700),
  { type: 'circle', silent: true, shape: { cx: 126, cy: 76, r: 4 }, style: { fill: C.red } },
  txt(136, 76, `Alta ${counts[4]}`, 9, C.sub, 700),
  { type: 'circle', silent: true, shape: { cx: 204, cy: 76, r: 4 }, style: { fill: C.orange } },
  txt(214, 76, `Média ${counts[3]}`, 9, C.sub, 700),

  txt(18, 98, 'SEVERIDADE', 8, C.mute, 800),
  txt(W * (compactMode ? 0.14 : 0.12), 98, 'ÚLTIMA ALTERAÇÃO', 8, C.mute, 800),
  txt(W * (compactMode ? 0.33 : 0.29), 98, 'HOST', 8, C.mute, 800),
  txt(W * (compactMode ? 0.52 : 0.47), 98, 'PROBLEMA / DADOS OPERACIONAIS', 8, C.mute, 800)
];
if (showAck) graphics.push(txt(W * 0.89, 98, HISTORY_MODE ? 'STATUS / ACK' : 'RECONHECIMENTO', 8, C.mute, 800));

graphics.push({
  type: 'line', silent: true,
  shape: { x1: 16, y1: 108, x2: W - 16, y2: 108 },
  style: { stroke: 'rgba(174,186,213,.12)', lineWidth: 1 }
});

function rowRender(params, api) {
  const idx = Number(api.value(1));
  const p = rows[idx];
  if (!p) return null;
  const key = String(idx);
  const y = api.coord([0, key])[1];
  let band = api.size([0, 1])[1];
  if (!Number.isFinite(band) || band <= 0) band = 38;
  const rh = Math.max(30, Math.min(44, band * 0.84));
  const x0 = api.coord([0, key])[0];
  const x100 = api.coord([100, key])[0];
  const cx = pct => api.coord([pct, key])[0];
  const sm = sevMeta(p);
  const recentFlag = isRecent(p);
  const rec = acknowledged(p);
  const recovered = isRecovered(p);
  const host = hostName(p);
  const group = groupName(p);
  const problem = String(p.name || p.description || 'Evento Zabbix');
  const op = String(p.opdata || '');
  const date = fmtDateTime(p.timestamp);
  const age = ageText(p.timestamp);

  const bg = idx % 2 === 0 ? 'rgba(13,27,46,.78)' : 'rgba(18,36,58,.58)';
  const children = [
    {
      type: 'rect',
      shape: { x: x0 + 2, y: y - rh / 2, width: Math.max(0, x100 - x0 - 5), height: rh, r: 7 },
      style: {
        fill: recentFlag ? 'rgba(23,199,213,.055)' : bg,
        stroke: recentFlag ? 'rgba(23,199,213,.20)' : 'rgba(174,186,213,.055)',
        lineWidth: 1
      }
    },
    {
      type: 'rect',
      shape: { x: x0 + 2, y: y - rh / 2, width: 3, height: rh, r: [7, 0, 0, 7] },
      style: { fill: sm.color }
    },
    { type: 'circle', shape: { cx: cx(1.7), cy: y, r: 4.2 }, style: { fill: sm.color } },
    {
      type: 'text',
      style: { x: cx(2.7), y, text: sm.short, font: '750 9px Inter, sans-serif', fill: sm.color, verticalAlign: 'middle' }
    },
    {
      type: 'text',
      style: { x: cx(compactMode ? 14 : 12), y: y - 7, text: date, font: '650 10px Inter, sans-serif', fill: C.text, verticalAlign: 'middle' }
    },
    {
      type: 'text',
      style: { x: cx(compactMode ? 14 : 12), y: y + 9, text: age, font: '500 9px Inter, sans-serif', fill: recentFlag ? C.cyan : C.mute, verticalAlign: 'middle' }
    },
    {
      type: 'text',
      style: {
        x: cx(compactMode ? 33 : 29), y: y - (showGroup && group ? 7 : 0), text: host,
        font: '700 10px Inter, sans-serif', fill: C.text, verticalAlign: 'middle',
        width: Math.max(80, cx(compactMode ? 50 : 45.5) - cx(compactMode ? 33 : 29) - 10), overflow: 'truncate', ellipsis: '…'
      }
    },
    {
      type: 'text',
      style: {
        x: cx(compactMode ? 52 : 47), y: y - (showOpdata && op ? 7 : 0), text: problem,
        font: '650 10px Inter, sans-serif', fill: C.text, verticalAlign: 'middle',
        width: Math.max(150, cx(showAck ? 87.5 : 98) - cx(compactMode ? 52 : 47) - 12), overflow: 'truncate', ellipsis: '…'
      }
    }
  ];

  if (showGroup && group) {
    children.push({
      type: 'text',
      style: {
        x: cx(29), y: y + 9, text: group, font: '500 8.5px Inter, sans-serif', fill: C.mute,
        verticalAlign: 'middle', width: Math.max(80, cx(45.5) - cx(29) - 10), overflow: 'truncate', ellipsis: '…'
      }
    });
  }

  if (showOpdata && op) {
    children.push({
      type: 'text',
      style: {
        x: cx(47), y: y + 9, text: op, font: '500 8.5px Inter, sans-serif', fill: C.mute,
        verticalAlign: 'middle', width: Math.max(150, cx(showAck ? 87.5 : 98) - cx(47) - 12), overflow: 'truncate', ellipsis: '…'
      }
    });
  }

  if (showAck) {
    let label = rec ? 'RECONHECIDO' : 'PENDENTE';
    let color = rec ? C.green : C.orange;
    if (HISTORY_MODE && recovered) { label = 'RECUPERADO'; color = C.green; }
    children.push(
      { type: 'circle', shape: { cx: cx(89.2), cy: y - 1, r: 3.5 }, style: { fill: color } },
      {
        type: 'text',
        style: {
          x: cx(90.2), y: y - 1, text: label, font: '750 8.5px Inter, sans-serif', fill: color,
          verticalAlign: 'middle', width: Math.max(55, x100 - cx(90.2) - 8), overflow: 'truncate', ellipsis: '…'
        }
      }
    );
  }

  return { type: 'group', children };
}

const zoom = total > visibleRows ? [
  {
    type: 'inside', yAxisIndex: 0, startValue: 0, endValue: visibleRows - 1,
    zoomOnMouseWheel: false, moveOnMouseWheel: true, moveOnMouseMove: true
  },
  {
    type: 'slider', yAxisIndex: 0, right: 5, top: 112, bottom: 18, width: 7,
    startValue: 0, endValue: visibleRows - 1, showDetail: false, showDataShadow: false,
    borderColor: 'transparent', backgroundColor: 'rgba(127,141,168,.08)',
    fillerColor: 'rgba(23,199,213,.24)', handleSize: 0,
    textStyle: { color: C.mute }
  }
] : [];

return {
  backgroundColor: 'transparent',
  animation: false,
  graphic: graphics,
  grid: { left: 16, right: total > visibleRows ? 18 : 12, top: 112, bottom: 16, containLabel: false },
  tooltip: {
    trigger: 'item',
    backgroundColor: 'rgba(5,11,22,.98)', borderColor: C.border, borderWidth: 1,
    padding: [11, 13], textStyle: { color: C.text, fontSize: 11 },
    formatter: function(params) {
      const raw = params && params.data;
      const idx = raw ? Number(raw[1]) : -1;
      const p = rows[idx];
      if (!p) return '';
      const sm = sevMeta(p);
      const tags = Array.isArray(p.tags) ? p.tags.map(t => {
        const k = t && (t.tag || t.name) ? (t.tag || t.name) : '';
        const v = t && t.value ? t.value : '';
        return [k, v].filter(Boolean).join(':');
      }).filter(Boolean).join(', ') : objName(p.tags);
      const op = p.opdata ? String(p.opdata) : '';
      const desc = String(p.name || p.description || 'Evento Zabbix');
      const state = HISTORY_MODE && isRecovered(p) ? 'Recuperado' : (acknowledged(p) ? 'Reconhecido' : 'Pendente de reconhecimento');
      let html = `<div style="min-width:320px;max-width:620px">`;
      html += `<div style="font-weight:800;font-size:12px;color:${sm.color};margin-bottom:7px">${esc(sm.label)} · ${esc(state)}</div>`;
      html += `<div style="font-weight:750;color:${C.text};margin-bottom:9px">${esc(desc)}</div>`;
      html += `<div style="color:${C.sub};line-height:1.65">`;
      html += `<b>Host:</b> ${esc(hostName(p))}<br>`;
      html += `<b>Última alteração:</b> ${esc(fmtDateTime(p.timestamp))} · ${esc(ageText(p.timestamp))}<br>`;
      if (groupName(p)) html += `<b>Grupo:</b> ${esc(groupName(p))}<br>`;
      if (op) html += `<b>Dados operacionais:</b> ${esc(op)}<br>`;
      html += `<b>Reconhecimento:</b> ${esc(ackSummary(p))}`;
      if (tags) html += `<br><b>Tags:</b> ${esc(tags)}`;
      html += `</div></div>`;
      return html;
    }
  },
  xAxis: { type: 'value', min: 0, max: 100, show: false },
  yAxis: {
    type: 'category', inverse: true, show: false,
    data: rows.map((_, i) => String(i)),
    boundaryGap: true
  },
  dataZoom: zoom,
  series: [
    {
      type: 'custom', coordinateSystem: 'cartesian2d', renderItem: rowRender,
      data: rows.map((_, i) => [0, String(i)]),
      encode: { x: 0, y: 1 },
      silent: false,
      progressive: 200,
      progressiveThreshold: 300
    }
  ]
};

