  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return String(v ?? '—');
  const z = n => String(n).padStart(2, '0');
  return `${z(d.getDate())}/${z(d.getMonth()+1)}/${d.getFullYear()} ${z(d.getHours())}:${z(d.getMinutes())}`;
}

function fmtAxis(v) {
  const ts = normalizeTime(v);
  if (ts === null) return '';
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return '';
  const z = n => String(n).padStart(2, '0');
  return `${z(d.getDate())}/${z(d.getMonth()+1)} ${z(d.getHours())}:00`;
}

function txt(x, y, text, size, color, weight, align='left', extra={}) {
  return {
    type:'text', silent:true,
    style:{
      x, y, text:String(text),
      font:`${weight || 500} ${size}px Inter, sans-serif`,
      fill:color || C.text, textAlign:align, textVerticalAlign:'middle', ...extra
    }
  };
}

function roundedCard(fill=C.card) {
  return {
    type:'rect', silent:true,
    shape:{x:1, y:1, width:Math.max(0, W-2), height:Math.max(0, H-2), r:14},
    style:{fill, stroke:C.border, lineWidth:1, shadowBlur:18, shadowColor:'rgba(0,0,0,.18)'}
  };
}

function accentLine(color) {
  return {
    type:'rect', silent:true,
    shape:{x:0, y:0, width:4, height:H, r:[14,0,0,14]},
    style:{fill:color}
  };
}

function problemsFromFrames() {
  const frames = (context.panel.data && context.panel.data.series) || [];
  const out = [];
  for (const frame of frames) {
    if (!frame || !frame.fields) continue;
    const pf = frame.fields.find(f => String(f.name).toLowerCase() === 'problems') ||
      frame.fields.find(f => f.config && f.config.custom && f.config.custom.type === 'problems');
    if (!pf) continue;
    for (const p of vals(pf)) {
      if (p && typeof p === 'object') out.push(p);
    }
  }
  return out;
}

function hourBucket(ts) {
  const d = new Date(ts);
  d.setMinutes(0, 0, 0);
  return d.getTime();
}

const problems = problemsFromFrames();
const buckets = new Map();

for (const p of problems) {
  const ts = normalizeTime(p && p.timestamp);
  if (ts === null) continue;
  const hour = hourBucket(ts);
  buckets.set(hour, (buckets.get(hour) || 0) + 1);
}

let ordered = [...buckets.entries()].sort((a,b) => a[0] - b[0]);

if (!ordered.length) {
  return {
    backgroundColor:'transparent',
    graphic:[
      roundedCard(), accentLine(C.cyan),
      txt(20,24,'ALERTAS POR HORA · HISTÓRICO',13,C.text,850),
      txt(20,48,'Quantidade de eventos históricos agrupados por hora no Business Charts.',10,C.sub,500),
      txt(20,H*0.53,'Sem eventos temporais disponíveis',16,C.text,750)
    ],
    xAxis:{show:false}, yAxis:{show:false}, series:[]
  };
}

/*
 * Preenche horas sem evento com zero para preservar a continuidade temporal,
 * mas cada bucket continua sendo desenhado como uma barra independente.
 */
const minTs = ordered[0][0];
const maxTs = ordered[ordered.length - 1][0];
const spanHours = Math.floor((maxTs - minTs) / 3600000) + 1;

if (spanHours <= 744) {
  const filled = [];
  for (let t = minTs; t <= maxTs; t += 3600000) {
    filled.push([t, buckets.get(t) || 0]);
  }
  ordered = filled;
}

const total = ordered.reduce((sum, point) => sum + point[1], 0);
const activeHours = ordered.reduce((sum, point) => sum + (point[1] > 0 ? 1 : 0), 0);
let peak = ordered[0];
for (const point of ordered) {
  if (point[1] > peak[1]) peak = point;
}

const showLabels = activeHours <= 36 && W >= 760;

return {
  backgroundColor:'transparent',
  animationDuration:450,

  graphic:[
    roundedCard(),
    accentLine(C.cyan),
    txt(20,24,'ALERTAS POR HORA · HISTÓRICO',13,C.text,850),
    txt(20,48,'Quantidade de eventos históricos por bucket de 1 hora. Cada coluna representa uma hora.',10,C.sub,500),
    txt(W-18,24,`${total.toLocaleString('pt-BR')} EVENTOS · ${activeHours.toLocaleString('pt-BR')} HORAS COM ALERTA`,9,C.cyan,850,'right'),
    txt(W-18,47,`Pico ${peak[1].toLocaleString('pt-BR')} · ${fmtDateTime(peak[0])}`,9,C.mute,650,'right')
  ],

  grid:{left:54,right:22,top:82,bottom:50},

  tooltip:{
    trigger:'axis',
    backgroundColor:'rgba(5,11,22,.98)',
    borderColor:C.border,
    borderWidth:1,
    textStyle:{color:C.text,fontSize:11},
    axisPointer:{type:'shadow',shadowStyle:{color:'rgba(23,199,213,.07)'}},
    formatter:function(params) {
      if (!params || !params.length) return '';
      const p = params[0];
      const value = Array.isArray(p.value) ? p.value[1] : p.value;
      const ts = Array.isArray(p.value) ? p.value[0] : p.axisValue;
      return `<b>${fmtDateTime(ts)}</b><br>${p.marker} Alertas: <b>${Number(value || 0).toLocaleString('pt-BR')}</b>`;
    }
  },

  xAxis:{
    type:'time',
    boundaryGap:[0.02,0.02],
    axisLine:{lineStyle:{color:'rgba(174,186,213,.18)'}},
    axisTick:{show:false},
    splitLine:{show:false},
    axisLabel:{
      color:C.mute,
      fontSize:9,
      hideOverlap:true,
      formatter:function(v){ return fmtAxis(v); }
    },
    axisPointer:{
      label:{
        formatter:function(p){ return fmtDateTime(p.value); }
      }
    }
  },

  yAxis:{
    type:'value',
    min:0,
    minInterval:1,
    axisLine:{show:false},
    axisTick:{show:false},
    splitLine:{lineStyle:{color:'rgba(174,186,213,.08)'}},
    axisLabel:{
      color:C.mute,
      fontSize:9,
      formatter:function(v){ return Number(v).toLocaleString('pt-BR'); }
    }
  },

  series:[{
    name:'Alertas por hora',
    type:'bar',
    data:ordered,
    barMaxWidth:30,
    barMinHeight:2,
    itemStyle:{
      color:new echarts.graphic.LinearGradient(0,0,0,1,[
        {offset:0,color:'rgba(23,199,213,1)'},
        {offset:1,color:'rgba(23,199,213,.50)'}
      ]),
      borderRadius:[5,5,1,1]
    },
    emphasis:{
      focus:'series',
      itemStyle:{shadowBlur:12,shadowColor:'rgba(23,199,213,.30)'}
    },
    label:{
      show:showLabels,
      position:'top',
      distance:5,
      color:C.sub,
      fontSize:9,
      fontWeight:700,
      formatter:function(p){
        const v = Array.isArray(p.value) ? Number(p.value[1]) : Number(p.value);
        return v > 0 ? v.toLocaleString('pt-BR') : '';
      }
    },
    z:3
  }]
};
